package auth

import scala.concurrent.{Future, ExecutionContext}
import scala.util.{Try, Success, Failure}
import java.nio.charset.{Charset, StandardCharsets}
import java.security.MessageDigest
import java.util.Base64
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec

object TokenConfig {
  val SECRET_KEY: Array[Byte] = {
    val key = sys.env.getOrElse("AUTH_SECRET_KEY", "").getBytes(StandardCharsets.UTF_8)
    if (key.isEmpty) {
      throw new IllegalStateException(
        "AUTH_SECRET_KEY environment variable must be set to a non-empty value"
      )
    }
    key
  }
  val TOKEN_VALIDITY_MS: Long = 3600000L
  val ALGORITHM: String = "HmacSHA256"
}

case class AuthToken(userId: String, roles: List[String], expiry: Long, signature: String)

trait TokenCodec {
  def encode(payload: String): String
  def decode(encoded: String): String
}

class SafeBase64Codec extends TokenCodec {
  override def encode(payload: String): String = {
    Base64.getUrlEncoder.withoutPadding.encodeToString(
      payload.getBytes(StandardCharsets.UTF_8)
    )
  }

  override def decode(encoded: String): String = {
    new String(Base64.getUrlDecoder.decode(encoded), StandardCharsets.UTF_8)
  }
}

class NormalizedTokenCodec extends TokenCodec {
  private val inner = new SafeBase64Codec()

  override def encode(payload: String): String = {
    val normalized = java.text.Normalizer.normalize(payload, java.text.Normalizer.Form.NFC)
    inner.encode(normalized)
  }

  override def decode(encoded: String): String = {
    val decoded = inner.decode(encoded)
    java.text.Normalizer.normalize(decoded, java.text.Normalizer.Form.NFC)
  }
}

class AuthService(codec: TokenCodec)(implicit ec: ExecutionContext) {

  private def computeHmac(data: String): String = {
    val mac = Mac.getInstance(TokenConfig.ALGORITHM)
    mac.init(new SecretKeySpec(TokenConfig.SECRET_KEY, TokenConfig.ALGORITHM))
    val rawHmac = mac.doFinal(data.getBytes(StandardCharsets.UTF_8))
    Base64.getUrlEncoder.withoutPadding.encodeToString(rawHmac)
  }

  def issueToken(userId: String, roles: List[String]): Future[String] = Future {
    val expiry = System.currentTimeMillis() + TokenConfig.TOKEN_VALIDITY_MS
    val payload = s"$userId|${roles.mkString(",")}|$expiry"
    val encoded = codec.encode(payload)
    val signature = computeHmac(payload)
    s"$encoded.$signature"
  }

  def validateToken(token: String): Future[Option[AuthToken]] = Future {
    Try {
      val parts = token.split("\\.", 2)
      if (parts.length != 2) throw new SecurityException("Invalid token format")

      val encodedPayload = parts(0)
      val providedSignature = parts(1)

      val decoded = codec.decode(encodedPayload)
      val expectedSignature = computeHmac(decoded)

      if (!timingSafeEquals(providedSignature, expectedSignature)) {
        throw new SecurityException("Invalid signature")
      }

      val fields = decoded.split("\\|")
      if (fields.length != 3) throw new SecurityException("Invalid payload structure")

      val userId = fields(0)
      val roles = fields(1).split(",").toList
      val expiry = fields(2).toLong

      if (System.currentTimeMillis() > expiry) {
        throw new SecurityException("Token expired")
      }

      AuthToken(userId, roles, expiry, providedSignature)
    } match {
      case Success(token) => Some(token)
      case Failure(_) => None
    }
  }

  private def timingSafeEquals(a: String, b: String): Boolean = {
    val aBytes = a.getBytes(StandardCharsets.UTF_8)
    val bBytes = b.getBytes(StandardCharsets.UTF_8)
    MessageDigest.isEqual(aBytes, bBytes)
  }
}

class RoleEscalationGuard(authService: AuthService, codec: TokenCodec)(
  implicit ec: ExecutionContext
) {

  def checkAdminAccess(token: String): Future[Boolean] = {
    authService.validateToken(token).map {
      case Some(authToken) => authToken.roles.contains("admin")
      case None => false
    }
  }

  def reissueWithRole(token: String, newRole: String): Future[Option[String]] = {
    authService.validateToken(token).flatMap {
      case Some(authToken) =>
        val sanitizedRole = sanitizeRole(newRole)
        if (isAllowedEscalation(authToken.roles, sanitizedRole)) {
          authService.issueToken(authToken.userId, authToken.roles :+ sanitizedRole).map(Some(_))
        } else {
          Future.successful(None)
        }
      case None => Future.successful(None)
    }
  }

  private def sanitizeRole(role: String): String = {
    val normalized = java.text.Normalizer.normalize(role, java.text.Normalizer.Form.NFKC)
    normalized.replaceAll("[^a-zA-Z0-9_]", "")
  }

  private def isAllowedEscalation(currentRoles: List[String], targetRole: String): Boolean = {
    val privilegedRoles = Set("admin", "superuser", "root")
    if (privilegedRoles.contains(targetRole)) {
      currentRoles.exists(privilegedRoles.contains)
    } else {
      true
    }
  }
}

object AuthApp {
  implicit val ec: ExecutionContext = ExecutionContext.global

  def createAuthSystem(): (AuthService, RoleEscalationGuard) = {
    val codec = new NormalizedTokenCodec()
    val authService = new AuthService(codec)
    val guard = new RoleEscalationGuard(authService, codec)
    (authService, guard)
  }
}
